import test from 'node:test';
import assert from 'node:assert/strict';
import { analyzePixels, compareFrames, estimateTranslation, motionAnalysisHtml } from '../../tools/lib/motion-analysis.mjs';

// Small geometric fixtures only. No character artwork is generated by these tests.
function frame(w=24,h=32,dx=0,dy=0,extra=false){
  const data=new Uint8Array(w*h*4);
  for(let y=5;y<28;y++)for(let x=6;x<18;x++)if(!(y>22&&x>10&&x<14))data.set([100,60,40,255],((y+dy)*w+x+dx)*4);
  if(extra)data.set([255,150,40,255],(10*w+4)*4);
  return data;
}
function sheet(frames,w=24,h=32){const d=new Uint8Array(w*h*16);frames.forEach((f,i)=>{for(let y=0;y<h;y++)d.set(f.subarray(y*w*4,(y+1)*w*4),((y+Math.floor(i/2)*h)*w*2+i%2*w)*4);});return d;}

test('bounding boxes, cell coordinates, sole proxies and body displacement follow known translation',()=>{
  const data=sheet([frame(),frame(24,32,2,-2),frame(),frame()]);const before=Buffer.from(data);
  const a=analyzePixels(data,48,64);
  assert.deepEqual(a.frames[0].coreBounds,[6,5,12,23]);
  assert.deepEqual(a.frames[1].cellOrigin,[24,0]);
  assert.deepEqual(a.frames[1].feetDisplacementFromFrame1,[2,-2]);
  assert.deepEqual(a.frames[1].bodyDisplacementFromFrame1,[2,-2]);
  assert.deepEqual(a.transitions[0].translationFit.shiftBToA,[-2,2]);
  assert.equal(a.transitions[0].translationFit.residual.changedPixels,0);
  assert.deepEqual(Buffer.from(data),before);
  assert.equal(a.decision,'pending');assert.equal(a.loopVerified,false);assert.equal(a.productionReady,false);
});
test('shape edits retain residual after translation while a pure shift does not',()=>{
  const a=frame(),b=frame(24,32,1,-1,true);
  const result=estimateTranslation(a,b,24,32,[-1,1]);
  assert.ok(result.residual.changedPixels>0);
  assert.ok(result.residual.meanPremultipliedRgbaError>0);
});
test('closing seam is measured as frame 4 to frame 1 and hidden transparent RGB is ignored',()=>{
  const a=frame(),b=frame();b.set([220,20,20,0],0);
  const result=analyzePixels(sheet([a,a,a,b]),48,64);
  assert.equal(result.loopSeam.from,4);assert.equal(result.loopSeam.to,1);
  assert.equal(result.loopSeam.raw.changedPixels,0);
});
test('out-of-cell translated support counts as a difference, empty frames and bad grid are reported',()=>{
  const a=new Uint8Array(4*4*4);a.set([255,0,0,255],0);
  assert.equal(compareFrames(a,a,4,4,0,-1).unionPixels,2);
  assert.throws(()=>analyzePixels(new Uint8Array(3*4*4),3,4),/Even 2x2/);
  const report=analyzePixels(new Uint8Array(4*4*4),4,4);
  assert.equal(report.technicalBlockers.length,4);
});
test('faint alpha at a cell edge is reported separately from actual character clipping',()=>{
  const data=frame();data.set([120,60,30,1],0);
  const result=analyzePixels(sheet([data,frame(),frame(),frame()]),48,64);
  assert.equal(result.frames[0].touchesCellBoundary,false);
  assert.equal(result.frames[0].faintAlphaAtCellBoundary,true);
  assert.equal(result.technicalBlockers.length,0);
  assert.equal(result.technicalWarnings.length,1);
  assert.equal(result.frames[0].alphaHistogram[1],1);
});
test('review uses original-sheet windows once, pending boundaries and adjustable unverified loop timing',()=>{
  const report={view:'nw',sheetSize:[48,64],originalSha256:'synthetic',...analyzePixels(sheet([frame(),frame(),frame(),frame()]),48,64)};
  const html=motionAnalysisHtml(report,Buffer.from('synthetic original fixture'));
  assert.equal((html.match(/data-sheet alt=/g)||[]).length,7);
  assert.equal((html.match(/data:image\/png;base64,/g)||[]).length,1);
  assert.match(html,/pending-motion-review/);assert.match(html,/250ms/);
  assert.doesNotMatch(html,/Idle v1/,'Shared viewer must not mislabel later revisions');
  assert.doesNotMatch(html,/canvas|toDataURL|toBlob/);
});
test('explicit image-plane shoe division is recorded without changing source pixels and rejects out-of-cell columns',()=>{
  const pixels=sheet([frame(),frame(),frame(),frame()]),before=Buffer.from(pixels);
  const a=analyzePixels(pixels,48,64,{footSplitX:14});
  assert.ok(a.frames.every(f=>f.feet.splitX===14));assert.equal(a.analysisParameters.footSplitX,14);
  assert.equal(a.loopVerified,false);assert.deepEqual(Buffer.from(pixels),before);
  assert.throws(()=>analyzePixels(pixels,48,64,{footSplitX:24}),/inside the cell/);
});
